  final value = map['darkMode'];
  if (value is! bool) {
    throw const SettingsFormatException('darkMode must be a boolean');
  }
  return value;
}

List<String> _tags(Map<String, Object?> map) {
  if (!map.containsKey('tags')) {
    return const [];
  }
  final value = map['tags'];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('tags must be a list of strings');
  }
  final tags = <String>[];
  for (final tag in value) {
    if (tag is! String) {
      throw const SettingsFormatException('tags must contain only strings');
    }
    if (tag.isEmpty) {
      throw const SettingsFormatException('tags must not contain empty tags');
    }
    tags.add(tag);
  }
  return List.unmodifiable(tags);
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search a [SearchModel] knows about.
enum SearchStatus { idle, loading, success, error }

/// Debounced search state: the newest query wins, stale answers are dropped.
class SearchModel extends ChangeNotifier {
  /// Searches with [fetcher] once [debounce] passed without a new query.
  new({required SearchFetcher fetcher, Duration debounce = _defaultDebounce})
    : _search = fetcher,
      _debounceDelay = debounce;

  static const _defaultDebounce = Duration(milliseconds: 300);

  final SearchFetcher _search;
  final Duration _debounceDelay;

  Timer? _timer;
  var _query = '';
  var _status = SearchStatus.idle;
  var _results = const <String>[];
  Object? _error;

  /// Identifies the current query; an answer to an older one is stale.
  var _generation = 0;
  var _disposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  /// Records [text] and schedules a fetch for it once the debounce elapses.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _error = null;
    _timer?.cancel();
    _generation++;
    if (text.isEmpty) {
      _timer = null;
      _status = SearchStatus.idle;
      _results = const [];
    } else {
      _status = SearchStatus.loading;
      final generation = _generation;
      _timer = Timer(_debounceDelay, () => unawaited(_fetch(text, generation)));
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed) {
      return;
    }
    try {
      final items = await _search(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.success;
      _results = List<String>.unmodifiable(items);
      _error = null;
    } on Object catch (e) {
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.error;
      _results = const [];
      _error = e;
    }
    notifyListeners();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

const _oneSecond = Duration(seconds: 1);

/// Counts down from the given duration to zero, one second at a time.
class CountdownController extends ChangeNotifier {
  new({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_oneSecond, _tick);
  }

  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
  }

  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _tick(Timer timer) {
    _remaining -= _oneSecond;
    if (_remaining <= Duration.zero) {
      _remaining = Duration.zero;
      _stop();
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the [controller]'s remaining time and drives it from three buttons.
class CountdownTimer extends StatefulWidget {
  const new({required this.controller, super.key, this.onFinished});

  final CountdownController controller;
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  var _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleControllerChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChange);
      widget.controller.addListener(_handleControllerChange);
      _finished = widget.controller.remaining == Duration.zero;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChange);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(_format(controller.remaining)),
        TextButton(onPressed: controller.start, child: const Text('Start')),
        TextButton(onPressed: controller.pause, child: const Text('Pause')),
        TextButton(onPressed: controller.reset, child: const Text('Reset')),
      ],
    );
  }

  void _handleControllerChange() {
    final finished = widget.controller.remaining == Duration.zero;
    setState(() {});
    if (finished && !_finished) {
      widget.onFinished?.call();
    }
    _finished = finished;
  }

  String _format(Duration remaining) {
    final minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final seconds = (remaining.inSeconds % 60).toString().padLeft(2, '0');
    return '$minutes:$seconds';
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results matching [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the search for the current query.
enum SearchStatus {
  /// No query is being searched for.
  idle,

  /// A fetch for the current query is in flight.
  loading,

  /// The fetch for the current query completed.
  success,

  /// The fetch for the current query threw.
  error,
}

/// Searches with [SearchFetcher] for the text passed to [onQueryChanged],
/// debouncing the calls and discarding results that arrive for a query that
/// is no longer current.
class SearchModel extends ChangeNotifier {
  /// Creates a model that searches with `fetcher` once `debounce` has passed
  /// without a further change of the query.
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Identifies the latest query, so that a response of an earlier one can be
  /// recognised and dropped.
  var _requestId = 0;

  var _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;

  /// The state of the search for [query].
  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch, empty otherwise.
  ///
  /// The list is unmodifiable.
  List<String> get results => _results;

  /// The object thrown by the latest failed fetch, `null` otherwise.
  Object? get error => _error;

  /// Stores [text] as the current [query] and schedules a fetch for it.
  ///
  /// Text equal to the current [query] does nothing. An empty text clears the
  /// results and the error and leaves the status [SearchStatus.idle].
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    // Any response still in flight is now for an earlier query.
    _requestId++;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
    } else {
      final requestId = _requestId;
      _timer = Timer(_debounce, () => unawaited(_fetch(text, requestId)));
    }
    notifyListeners();
  }

  Future<void> _fetch(String text, int requestId) async {
    if (_isStale(requestId)) {
      return;
    }
    _timer = null;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    try {
      final values = await _fetcher(text);
      if (_isStale(requestId)) {
        return;
      }
      _results = List<String>.unmodifiable(values);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_isStale(requestId)) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  bool _isStale(int requestId) => _disposed || requestId != _requestId;

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

/// Thrown by [parseSettings] when a document cannot be read as [Settings].
///
/// The [message] always names the offending key when one key is at fault.
class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// User preferences, as stored in a JSON document.
///
/// The constructor does not validate; [parseSettings] is the checked entry
/// point and rejects an empty [username], a [fontSize] outside
/// [minFontSize]..[maxFontSize], and an empty tag.
@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = defaultFontSize,
    this.darkMode = false,
    this.tags = const [],
  });

  /// Smallest accepted [fontSize].
  static const minFontSize = 8;

  /// Largest accepted [fontSize].
  static const maxFontSize = 72;

  /// Value used when the `fontSize` key is absent.
  static const defaultFontSize = 14;

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;

  /// The JSON representation read back by [parseSettings].
  Map<String, Object?> toJson() => {
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': tags,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags);

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Reads [json] as a settings document.
///
/// Throws [SettingsFormatException], and nothing else, for any input that is
/// not a settings document. Unknown keys are ignored.
Settings parseSettings(String json) {
  final Object? document;
  try {
    document = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('not valid JSON: ${error.message}');
  }
  if (document is! Map<String, Object?>) {
    throw const SettingsFormatException('top level must be a JSON object');
  }
  return Settings(
    username: _readUsername(document),
    fontSize: _readFontSize(document),
    darkMode: _readDarkMode(document),
    tags: _readTags(document),
  );
}

String _readUsername(Map<String, Object?> document) {
  final value = document['username'];
  if (value is! String) {
    throw const SettingsFormatException('username: expected a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('username: must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> document) {
  final value = document['fontSize'];
  if (value == null) {
    return Settings.defaultFontSize;
  }
  if (value is! num || !value.isFinite) {
    throw const SettingsFormatException('fontSize: expected an integer');
  }
  final fontSize = value.toInt();
  if (fontSize != value) {
    throw const SettingsFormatException(
      'fontSize: expected an integer without a fractional part',
    );
  }
  if (fontSize < Settings.minFontSize || fontSize > Settings.maxFontSize) {
    throw const SettingsFormatException(
      'fontSize: must be between '
      '${Settings.minFontSize} and ${Settings.maxFontSize}',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> document) {
  final value = document['darkMode'];
  if (value == null) {
    return false;
  }
  if (value is! bool) {
    throw const SettingsFormatException('darkMode: expected a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> document) {
  final value = document['tags'];
  if (value == null) {
    return const [];
  }
  if (value is! List<Object?>) {
    throw const SettingsFormatException('tags: expected a list of strings');
  }
  final tags = <String>[];
  for (final tag in value) {
    if (tag is! String) {
      throw const SettingsFormatException('tags: every entry must be a string');
    }
    if (tag.isEmpty) {
      throw const SettingsFormatException('tags: no entry may be empty');
    }
    tags.add(tag);
  }
  return List.unmodifiable(tags);
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from a fixed duration to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose], which also cancels a running countdown.
class CountdownController extends ChangeNotifier {
  new({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown reaches zero.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking; does nothing while running or once [remaining] is zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
    notifyListeners();
  }

  /// Stops ticking and keeps [remaining]; does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancelTimer();
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to the configured duration.
  void reset() {
    _cancelTimer();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _cancelTimer();
    super.dispose();
  }

  void _onTick() {
    final next = _remaining - _tick;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      _cancelTimer();
    }
    notifyListeners();
  }

  void _cancelTimer() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the [controller]'s remaining time as `mm:ss` with start, pause and
/// reset buttons.
///
/// The controller is owned by the caller: this widget never disposes it, so the
/// same controller can be handed to another [CountdownTimer] afterwards.
class CountdownTimer extends StatefulWidget {
  const new({required this.controller, super.key, this.onFinished});

  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late bool _finished;

  @override
  void initState() {
    super.initState();
    _finished = _isFinished(widget.controller);
    widget.controller.addListener(_handleControllerChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChanged);
      _finished = _isFinished(widget.controller);
      widget.controller.addListener(_handleControllerChanged);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChanged);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(_format(controller.remaining)),
        TextButton(onPressed: controller.start, child: const Text('Start')),
        TextButton(onPressed: controller.pause, child: const Text('Pause')),
        TextButton(onPressed: controller.reset, child: const Text('Reset')),
      ],
    );
  }

  bool _isFinished(CountdownController controller) =>
      !controller.isRunning && controller.remaining == Duration.zero;

  void _handleControllerChanged() {
    if (!mounted) {
      return;
    }
    final finished = _isFinished(widget.controller);
    final justFinished = finished && !_finished;
    setState(() {
      _finished = finished;
    });
    if (justFinished) {
      widget.onFinished?.call();
    }
  }

  String _format(Duration value) {
    final minutes = value.inMinutes.toString().padLeft(2, '0');
    final seconds = (value.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }
}

