    super.dispose();
  }

  void _cancelTimer() {
    _timer?.cancel();
    _timer = null;
  }

  void _onTick(Timer timer) {
    final next = _remaining - _tick;
    _remaining = next < Duration.zero ? Duration.zero : next;
    if (_remaining == Duration.zero) {
      _cancelTimer();
    }
    notifyListeners();
  }
}

