import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Identifies the newest accepted query. A fetch whose token no longer
  /// matches belongs to a superseded query and its outcome is discarded.
  var _token = 0;
  var _disposed = false;

  var _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    _token++;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }
    final token = _token;
    _timer = Timer(_debounce, () => unawaited(_fetch(text, token)));
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }

  Future<void> _fetch(String text, int token) async {
    _timer = null;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    try {
      final found = List<String>.unmodifiable(await _fetcher(text));
      if (_disposed || token != _token) {
        return;
      }
      _status = SearchStatus.success;
      _results = found;
      _error = null;
    } on Object catch (e) {
      if (_disposed || token != _token) {
        return;
      }
      _status = SearchStatus.error;
      _results = const <String>[];
      _error = e;
    }
    notifyListeners();
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

const _usernameKey = 'username';
const _fontSizeKey = 'fontSize';
const _darkModeKey = 'darkMode';
const _tagsKey = 'tags';

const _minFontSize = 8;
const _maxFontSize = 72;

/// User preferences, as stored in and restored from a JSON document.
@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  }) : assert(username != '', 'username must not be empty'),
       assert(
         fontSize >= _minFontSize && fontSize <= _maxFontSize,
         'fontSize must be within $_minFontSize..$_maxFontSize',
       );

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;

  Map<String, Object?> toJson() => {
    _usernameKey: username,
    _fontSizeKey: fontSize,
    _darkModeKey: darkMode,
    _tagsKey: tags,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags);

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown by [parseSettings] for any document it cannot turn into [Settings].
class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Reads a [Settings] value from a JSON document.
///
/// Throws a [SettingsFormatException] when [json] is not valid JSON, when its
/// top level is not an object, or when a known key is missing, holds a value
/// of the wrong type, or holds a value outside its range. The message always
/// names the offending key. Unknown keys are ignored.
Settings parseSettings(String json) {
  final decoded = _decodeJson(json);
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object.',
    );
  }
  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

Object? _decodeJson(String source) {
  try {
    return jsonDecode(source) as Object?;
  } on FormatException {
    throw const SettingsFormatException('The document is not valid JSON.');
  }
}

String _readUsername(Map<String, Object?> json) {
  final value = json[_usernameKey];
  if (value == null) {
    throw const SettingsFormatException(
      'Key "$_usernameKey" is required and is missing.',
    );
  }
  if (value is! String) {
    throw const SettingsFormatException(
      'Key "$_usernameKey" must hold a string.',
    );
  }
  if (value.isEmpty) {
    throw const SettingsFormatException(
      'Key "$_usernameKey" must not hold an empty string.',
    );
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  if (!json.containsKey(_fontSizeKey)) {
    return 14;
  }
  final value = json[_fontSizeKey];
  if (value is! int) {
    throw const SettingsFormatException(
      'Key "$_fontSizeKey" must hold an integer without a fractional part.',
    );
  }
  if (value < _minFontSize || value > _maxFontSize) {
    throw const SettingsFormatException(
      'Key "$_fontSizeKey" must hold a value '
      'within $_minFontSize..$_maxFontSize.',
    );
  }
  return value;
}

bool _readDarkMode(Map<String, Object?> json) {
  if (!json.containsKey(_darkModeKey)) {
    return false;
  }
  final value = json[_darkModeKey];
  if (value is! bool) {
    throw const SettingsFormatException(
      'Key "$_darkModeKey" must hold a boolean.',
    );
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  if (!json.containsKey(_tagsKey)) {
    return const [];
  }
  final value = json[_tagsKey];
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      'Key "$_tagsKey" must hold a list of strings.',
    );
  }
  final tags = <String>[];
  for (final element in value) {
    if (element is! String) {
      throw const SettingsFormatException(
        'Key "$_tagsKey" must hold strings only.',
      );
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        'Key "$_tagsKey" must not hold an empty string.',
      );
    }
    tags.add(element);
  }
  return tags;
}

import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  var _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;
  Timer? _debounceTimer;
  var _fetchId = 0;
  var _isDisposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_isDisposed || text == _query) {
      return;
    }
    _query = text;
    _debounceTimer?.cancel();
    _debounceTimer = null;
    if (text.isEmpty) {
      // Nothing to fetch: whatever is in flight belongs to an older query.
      _fetchId++;
      _status = SearchStatus.idle;
      _results = const [];
      _error = null;
      notifyListeners();
      return;
    }
    notifyListeners();
    _debounceTimer = Timer(_debounce, _startFetch);
  }

  @override
  void dispose() {
    _isDisposed = true;
    _debounceTimer?.cancel();
    _debounceTimer = null;
    super.dispose();
  }

  void _startFetch() {
    _debounceTimer = null;
    if (_isDisposed) {
      return;
    }
    _status = SearchStatus.loading;
    notifyListeners();
    unawaited(_fetch(++_fetchId, _query));
  }

  Future<void> _fetch(int fetchId, String query) async {
    try {
      final results = await _fetcher(query);
      if (_isDisposed || fetchId != _fetchId) {
        return;
      }
      _results = List.unmodifiable(results);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_isDisposed || fetchId != _fetchId) {
        return;
      }
      _results = const [];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

const _oneSecond = Duration(seconds: 1);

class CountdownController extends ChangeNotifier {
  new({required this._duration}) : _remaining = _duration;

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_oneSecond, _tick);
  }

  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
    notifyListeners();
  }

  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }

  void _tick(Timer timer) {
    final next = _remaining - _oneSecond;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      _stop();
    }
    notifyListeners();
  }
}

class CountdownTimer extends StatefulWidget {
  const new({required this.controller, this.onFinished, super.key});

  final CountdownController controller;
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  var _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleUpdate);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleUpdate);
      widget.controller.addListener(_handleUpdate);
      _finished = widget.controller.remaining == Duration.zero;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleUpdate);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      Text(_formatted(widget.controller.remaining)),
      Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          TextButton(
            onPressed: widget.controller.start,
            child: const Text('Start'),
          ),
          TextButton(
            onPressed: widget.controller.pause,
            child: const Text('Pause'),
          ),
          TextButton(
            onPressed: widget.controller.reset,
            child: const Text('Reset'),
          ),
        ],
      ),
    ],
  );

  String _formatted(Duration value) {
    final minutes = value.inMinutes.toString().padLeft(2, '0');
    final seconds = (value.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }

  void _handleUpdate() {
    final hasFinished = widget.controller.remaining == Duration.zero;
    final justFinished = hasFinished && !_finished;
    setState(() {
      _finished = hasFinished;
    });
    if (justFinished) {
      widget.onFinished?.call();
    }
  }
}

